var INDUSTRIA=[{t:"DePuy Synthes — ATTUNE Revision Hinge Knee",v:"Non ridichiarato oggi: il raccoglitore notturno non è passato, dato più recente resta quello di ieri pomeriggio (richiamo openFDA aperto, classificato, avviato 19 maggio 2026)."},{t:"Zimmer Biomet — ciotole e spatole in kit Medline TOTAL KNEE PACK",v:"Non ridichiarato oggi: il raccoglitore notturno non è passato, dato più recente resta quello di ieri pomeriggio (richiamo openFDA aperto, classificato, avviato 10 giugno 2026)."}];
